#[test]
fn measured_robotics_contact_completes_without_shortcutting_mobile_bodies() {
    let (mut app, keys) = measured_app(ROBOTICS_ENDPOINT);
    let worker = keys[&4294966764];
    let target = keys[&1271310317352];
    let definition = registry::entity("RoboticsBay").unwrap();
    let goal = Vec3::new(-20.9615535736084, 0.0, -14.780961036682129);
    app.world_mut()
        .entity_mut(target)
        .insert(UnderConstruction {
            remaining: 1.0,
            total: 1.0,
            cost: definition.cost,
            free_worker_origin: None,
        });
    app.world_mut().entity_mut(worker).insert((
        ConstructOrder { target },
        MoveOrder { target: goal },
        PlannedPath {
            goal,
            next: 0,
            waypoints: vec![Vec3::new(-15.25, 0.0, -17.25)],
        },
    ));
    let bank_before = {
        let bank = app.world().resource::<Economies>().get(Team::Player(0));
        (bank.ore, bank.crystal)
    };
    let worker_hp = app.world().get::<Health>(worker).unwrap().current;
    let worker_radius = app.world().get::<Selectable>(worker).unwrap().radius;
    for tick in 0..900 {
        let before = app.world().get::<Transform>(worker).unwrap().translation;
        let bodies = {
            let mut query =
                app.world_mut()
                    .query::<(Entity, &Transform, &Selectable, Option<&MovementDomain>)>();
            query
                .iter(app.world())
                .filter(|(entity, _, _, domain)| {
                    *entity != worker && domain.is_none_or(|domain| *domain != MovementDomain::Air)
                })
                .map(|(_, transform, body, _)| (transform.translation, body.radius))
                .collect::<Vec<_>>()
        };
        app.update();
        let after = app.world().get::<Transform>(worker).unwrap().translation;
        assert!(
            xz_distance(before, after) <= (2.5 + UNIT_SEPARATION_MAX_SPEED) / 30.0 + 0.002,
            "worker must move normally without teleporting"
        );
        for (position, radius) in bodies {
            assert!(
                distance_point_to_xz_segment(position, before, after) + 0.002
                    >= worker_radius + radius,
                "worker step entered a real body at {position:?}: {before:?}->{after:?}"
            );
        }
        assert_eq!(
            app.world().get::<Health>(worker).unwrap().current,
            worker_hp
        );
        let bank = app.world().resource::<Economies>().get(Team::Player(0));
        assert_eq!(
            (bank.ore, bank.crystal),
            bank_before,
            "fixture completion cannot grant resources"
        );
        if tick < 5 || tick % 90 == 0 {
            println!(
                "robotics tick{tick} worker={:?} move={:?} path={:?} remaining={:?}",
                app.world().get::<Transform>(worker).unwrap().translation,
                app.world().get::<MoveOrder>(worker).map(|o| o.target),
                app.world()
                    .get::<PlannedPath>(worker)
                    .map(|p| (p.next, p.waypoints.clone())),
                app.world()
                    .get::<UnderConstruction>(target)
                    .map(|s| s.remaining)
            );
        }
        if app.world().get::<UnderConstruction>(target).is_none() {
            println!("robotics completed tick{tick}");
            return;
        }
    }
    panic!("measured Robotics contact failed original900tick construction budget");
}
